from fastapi import APIRouter, Depends
from api.auth import get_current_user
from api.dependencies import get_content_repo
from api.schemas import PublishConfigResponse, UpdatePublishConfigRequest, PlatformPublishConfig
from content_engine.models import Platform

router = APIRouter(prefix='/api/settings', tags=['settings'], dependencies=[Depends(get_current_user)])

@router.get('/publish', response_model=PublishConfigResponse)
async def get_publish_config(repo=Depends(get_content_repo)):
    configs = await repo.get_publish_configs()
    # Ensure all platforms have entries
    platform_map = {c.platform: c for c in configs}
    result = []
    for platform in Platform:
        if platform.value in platform_map:
            c = platform_map[platform.value]
            result.append(PlatformPublishConfig(
                platform=c.platform,
                enabled=c.enabled,
                delay_hours=c.delay_hours,
                pillar_overrides=c.pillar_overrides or {}
            ))
        else:
            result.append(PlatformPublishConfig(platform=platform.value))
    return PublishConfigResponse(platforms=result)

@router.put('/publish', response_model=PublishConfigResponse)
async def update_publish_config(
    req: UpdatePublishConfigRequest,
    repo=Depends(get_content_repo),
    user=Depends(get_current_user)
):
    for config in req.platforms:
        await repo.upsert_publish_config(
            platform=config.platform,
            enabled=config.enabled,
            delay_hours=config.delay_hours,
            pillar_overrides=config.pillar_overrides,
            updated_by=user.id if hasattr(user, 'id') else None
        )
    return await get_publish_config(repo)
```

Add auto-publish logic to approval flow in api/routes/content.py:
```python
@router.post('/drafts/{row_id}/approve', response_model=ApproveResponse)
async def approve_draft(
    row_id: int,
    repo=Depends(get_content_repo),
    postiz=Depends(get_postiz_client)
):
    row = await repo.get_content_row(row_id)
    if not row:
        raise HTTPException(404, 'Row not found')

    # Check auto-publish config
    if not row.require_manual_approval:
        configs = await repo.get_publish_configs()
        config_map = {c.platform: c for c in configs}

        auto_publish_at = None
        for platform, enabled in row.platforms.items():
            if not enabled:
                continue
            config = config_map.get(platform)
            if config and config.enabled:
                # Check pillar override
                if row.pillar and config.pillar_overrides.get(row.pillar) is False:
                    continue
                # Calculate auto-publish time
                delay = timedelta(hours=config.delay_hours)
                publish_time = datetime.utcnow() + delay
                if auto_publish_at is None or publish_time > auto_publish_at:
                    auto_publish_at = publish_time

        if auto_publish_at:
            await repo.update_auto_publish_at(row_id, auto_publish_at)

    await repo.update_status(row_id, ContentStatus.APPROVED)
    # ... rest of Postiz integration
```

