import { useState, useEffect } from 'react';
import { formatDistanceToNow, differenceInSeconds, isPast } from 'date-fns';
import { Clock, AlertCircle } from 'lucide-react';

interface AutoPublishCountdownProps {
  publishAt: string;  // ISO datetime
  onExpired?: () => void;
}

export function AutoPublishCountdown({ publishAt, onExpired }: AutoPublishCountdownProps) {
  const [timeLeft, setTimeLeft] = useState('');
  const [isExpired, setIsExpired] = useState(false);

  useEffect(() => {
    const updateCountdown = () => {
      const target = new Date(publishAt);
      if (isPast(target)) {
        setIsExpired(true);
        setTimeLeft('Publishing...');
        onExpired?.();
        return;
      }

      const seconds = differenceInSeconds(target, new Date());
      if (seconds < 3600) {
        // Show minutes
        const minutes = Math.ceil(seconds / 60);
        setTimeLeft(`${minutes}m`);
      } else {
        // Show hours:minutes
        const hours = Math.floor(seconds / 3600);
        const mins = Math.floor((seconds % 3600) / 60);
        setTimeLeft(`${hours}h ${mins}m`);
      }
    };

    updateCountdown();
    const interval = setInterval(updateCountdown, 60000); // Update every minute

    return () => clearInterval(interval);
  }, [publishAt, onExpired]);

  if (!publishAt) return null;

  return (
    <div className={
      `flex items-center gap-1 text-xs px-2 py-1 rounded-full ` +
      (isExpired 
        ? 'bg-orange-100 text-orange-700' 
        : 'bg-blue-100 text-blue-700')
    }>
      {isExpired ? <AlertCircle className="h-3 w-3" /> : <Clock className="h-3 w-3" />}
      <span>Auto-publish {isExpired ? 'now' : `in ${timeLeft}`}</span>
    </div>
  );
}
